}

/// How many table rows were drawn on this thread since last asked, laid out
/// in view or measured out of it.
#[cfg(test)]
pub(crate) fn rows_drawn() -> usize {
    ROWS_DRAWN.with(|drawn| drawn.replace(0))
}

