                    .and_then(|anchor| hidden_anchor::preview(&anchor, &text, &project_dir));
                match compiled {
                    Ok(compiled) => match feed.send(text, compiled.user_prompt) {
                        Ok(()) => ToTask::Sent,
                        Err(_) => ToTask::Over,
                    },
                    Err(err) => ToTask::Failed(format!("{err:#}")),
                }
