                        Notification::error(error).title("Could not send to the task"),
                        cx,
                    );
                    this.chat_input.update(cx, |input, cx| {
                        input.take_back(text, attached_text, window, cx)
                    });
                }
            })
            .ok();
        })
        .detach();
    }

