        window.find(("send-option", 2usize));
        window.press("enter", cx);
        assert_eq!(chat_input.read(cx).editor.read(cx).value().as_ref(), "");
        assert!(chat_input.read(cx).attachments().is_empty());
    })
    .unwrap();
