    .unwrap();
    assert_eq!(chat_input.read_with(cx, |input, _| input.mode()), SendMode::Both);

    // A message that couldn't be sent comes back, ahead of anything
    // written since, with what was attached.
    cx.update_window(handle, |_, window, cx| {
